"""infra/config/providers/drivers/trace/langfuse: the lab's Langfuse — the `LABS_LANGFUSE_*` variables compose seeds it with."""

from pydantic_settings import SettingsConfigDict

from infra.config.base import BaseSettings, Secret


class LangfuseSettings(BaseSettings):
    """Endpoint, keys (generated by `make env`, no default), project, environment and export batching."""

    model_config = SettingsConfigDict(env_prefix="LABS_LANGFUSE_")

    host: str = "localhost"
    port: int = 28100
    public_key: str = ""
    secret_key: Secret = Secret("")
    project: str = "labs-deeptrack"
    environment: str = "labs"
    flush_interval: float = 5.0

    @property
    def url(self) -> str:
        """Langfuse's web, API and OTLP endpoint on the host."""
        return f"http://{self.host}:{self.port}"
